const app=document.querySelector('#app');let me=null,data=null,platform=null,financeData=null,financeFilters={currency:'GBP',kind:'',status:'',organisation:'',from:'',to:''},connection=null,view='dashboard',org='',message='',extended=null,preview=null,expenseData=null,expenseDestinations=null,expenseFilters={mode:null,status:'',category:'',from:'',to:''},activityData=[],activityFilters={organisation:'',status:'',module:'',search:'',access:false},pendingExpenseId=new URLSearchParams(location.search).get('expense')||'';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const field=(label,name,value='',type='text',attrs='')=>`<label>${esc(label)}<input name="${name}" type="${type}" value="${esc(value)}" ${attrs}></label>`;
const select=(label,name,choices,value='')=>`<label>${esc(label)}<select name="${name}">${choices.map(c=>{let [v,l]=Array.isArray(c)?c:[c,c];return `<option value="${esc(v)}" ${v===value?'selected':''}>${esc(l)}</option>`}).join('')}</select></label>`;
const card=(t,b)=>`<section class="card"><h2>${esc(t)}</h2>${b}</section>`;
const table=(headers,rows)=>rows.length?`<div class="tablewrap"><table><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:'<p class="empty">No records.</p>';
const stat=items=>`<div class="cards">${items.map(([l,n,s])=>`<section class="card stat"><span>${esc(l)}</span><strong>${esc(n)}</strong><small>${esc(s)}</small></section>`).join('')}</div>`;
const button=(label,action,extra='')=>`<button data-action="${action}" ${extra}>${esc(label)}</button>`;
async function api(path,body){document.body.setAttribute('aria-busy','true');let r;try{r=await fetch(path,{method:body===undefined?'GET':'POST',headers:body===undefined?{}:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)})}finally{document.body.removeAttribute('aria-busy')}let d=await r.json();if(!r.ok){if(r.status===401&&me){me=null;history.replaceState(null,'','/login');authPage()}throw Error(d.error||'Request failed')}return d}
async function refresh(){if(me.role==='owner'){financeData=await api('/api/platform/finance');platform=await api('/api/platform/overview');platform.organisations=platform.organisations.filter(w=>!w.archived&&!isExampleWorkspace(w)).map(w=>({...w,name:workspaceName(w)}));platform.settings=await api('/api/platform/settings');for(let o of platform.organisations){o.connection=(await api('/api/'+o.id+'/state')).connection}activityData=await Promise.all(platform.organisations.map(w=>api('/api/'+w.id+'/activity')));}if(org){data=await api('/api/'+org+'/workspace');data.workspace.name=workspaceName(data.workspace);data.workspace.demoRequests=[];data.workspace.equipment=data.workspace.equipment.filter(e=>!isExampleRecord(e));data.records=data.records.filter(r=>!isExampleRecord(r));connection=await api('/api/'+org+'/state');extended=me.role==='owner'&&!data.workspace.ownerRecordAccess?{entities:[],rules:[],sources:[],capabilities:{},templates:[]}:await api('/api/'+org+'/platform');expenseData=data.workspace.modules.expenses?await api('/api/'+org+'/expenses'):null;if(expenseData){expenseData.allRecords=expenseData.records;expenseFilters.mode??=expenseData.settings.dataMode==='Test'?'Test':'Production';expenseData.records=filteredExpenses();}connection.records=(connection.records||[]).filter(r=>!isExampleRecord(r));extended.entities=(extended.entities||[]).filter(r=>!isExampleRecord(r));if(me.role!=='owner'&&me.role==='admin')activityData=[await api('/api/'+org+'/activity')];}render()}
function authPage(){let path=location.pathname,register=path==='/register',accept=path==='/accept-invite',owner=path==='/owner-login';app.innerHTML=`<div class="topnotice">Secure access to your organisation workspace</div><div class="auth-layout"><section class="auth-brand"><img class="logo" src="logo.png" alt="OperaOS"><span class="auth-kicker">Your operations, connected</span><h2>One workspace.<br>A clearer workday.</h2><p>Manage people, requests and records with the tools your organisation needs.</p><div class="auth-feature">Organisations · Workflows · Reporting</div></section><section class="card auth"><span class="auth-kicker">${owner?'Platform owner':register?'Get started':'Your workspace'}</span><h1>${register?'Create your workspace':accept?'Accept your invitation':owner?'Welcome back, owner':'Welcome back'}</h1><p>${register?'Your account becomes administrator of your new, separate workspace.':'Your account determines your portal and organisation.'}</p><form id="auth" class="form">${register||accept?field('Your name','name','','text','required maxlength="100"'):''}${field('Email','email','','email','required autocomplete="username"')}${field('Password','password','','password','required minlength="12" maxlength="128" autocomplete="'+(register||accept?'new-password':'current-password')+'"')}${register?field('Organisation name','organisation','','text','required')+select('Choose your workspace setup','template',[['general','General administration'],['workforce','People and attendance'],['equipment','Assets and equipment requests'],['documents','Documents and renewal tasks'],['expenses','Expense approval']])+ '<p class="auth-hint">Start with a ready-made setup, then choose modules and rules for your organisation during onboarding.</p>':''}<button class="primary">${register?'Create workspace':accept?'Create account':'Sign in'}</button></form><p class="error" role="alert">${esc(message)}</p><div class="auth-links"><a href="/login" class="${!owner&&!register?'current':''}">Team login</a><a href="/owner-login" class="${owner?'current':''}">Owner login</a><a href="/register" class="${register?'current':''}">Create workspace</a></div><p class="auth-hint">Your account opens the workspace and permissions assigned to you.</p></section></div>`;document.querySelector('#auth').onsubmit=async e=>{e.preventDefault();let b=Object.fromEntries(new FormData(e.target));if(accept)b.token=new URLSearchParams(location.search).get('token');try{let d=await api(register?'/auth/register':accept?'/auth/accept-invite':'/auth/login',b);me=d.user;org=me.org;message='';view=register?'onboarding':pendingExpenseId?'expenses':'dashboard';history.replaceState(null,'',d.route+(pendingExpenseId?'?expense='+encodeURIComponent(pendingExpenseId):''));await refresh()}catch(e){message=e.message;authPage()}}}
function navigation(){if(me.role==='owner')return [['dashboard','Platform dashboard'],['organisations','Organisations'],['finance','Company finances'],['neworganisation','New organisation'],['activity','Runtime Activity'],['catalogue','Module catalogue'],['platformsettings','Plans & platform settings'],...(org?[['onboarding','Organisation setup'],['people','Users & invitations'],['connections','Data Connections'],...(data?.workspace.modules.expenses?[['expenses','Expense Approval']]:[])]:[])];let w=data.workspace,list=[['dashboard','Dashboard']];if(me.role==='admin')list.push(['onboarding','Organisation setup'],['people','Users & permissions'],['settings','Operational rules'],['connections','Data Connections']);if(w.active&&w.modules.attendance&&(me.role==='admin'||['employee','manager'].includes(me.kind)))list.push(['attendance',me.role==='admin'?'Attendance records':'My attendance'],['connected','Connected attendance']);if(w.active&&w.modules.equipment&&(me.role==='admin'||['student','approver','manager'].includes(me.kind)))list.push(['requests',me.kind==='approver'?'Assigned approvals':me.role==='admin'?'Requests & issue':'My requests']);if(me.role==='admin'&&w.modules.equipment)list.push(['inventory','Inventory'],['connected','Connected equipment']);if(w.modules.reporting)list.push(['reports',me.role==='admin'?'Organisation reports':'Personal history']);if(w.modules.notifications)list.push(['notifications','Notifications']);if(me.role==='admin')list.push(['activity','Runtime Activity'],['csv','CSV data']);if(w.modules.tasks)list.push(['tasks','Tasks & schedules']);if(w.modules.documents)list.push(['documents','Documents & records']);if(me.role==='admin')list.push(['automations','Automation templates'],['integration','Data Integration Centre']);if(w.modules.expenses)list.push(['expenses',me.kind==='employee'?'My expenses':me.role==='admin'?'Expense reports':'Expense approvals']);return list}
function render(){if(!me)return authPage();let nav=navigation();if(!nav.some(n=>n[0]===view))view='dashboard';let title=me.role==='owner'?'OperaOS Owner Portal':'Organisation / User Portal';app.innerHTML=`<aside><img class="logo" src="logo.png" alt="OperaOS"><p>${esc(title)}</p><nav>${nav.map(([id,label])=>button(label,'view',`data-view="${id}" class="${id===view?'active':''}"`)).join('')}</nav><footer>Authenticated account<br>Backend organisation permissions</footer></aside><div class="main"><header><span class="badge">${esc(title)}</span><span>${esc(me.name)} · ${esc(me.email)} · ${esc(me.role==='admin'?'Organisation Admin':me.role==='owner'?'Owner':me.kind)}</span>${button('Logout','logout')}</header><main><div class="eyebrow">${esc(data?.workspace.name||'OperaOS platform')}</div><h1>${esc(nav.find(n=>n[0]===view)[1])}</h1><div class="notice">Your organisation workspace · Permissions and connected services are managed by your administrator.</div>${message?`<p class="feedback" role="status">${esc(message)}</p>`:''}${content()}</main></div>`;bind()}
function connectionCard(){let c=connection?.connection||{status:'Not connected'},rows=connection?.records||[];return card('Connected runtime snapshot',`<p><b>${esc(c.status)}</b> · Last successful sync: ${esc(c.lastSync||'Never')}</p>${stat([['Connected records',rows.length,'Endpoint read-back only'],['Completed hours',rows.reduce((n,r)=>n+(r.checkOut?r.hours||0:0),0).toFixed(4),'Connected attendance'],['Approved',rows.filter(r=>r.status==='approved').length,'Returned by workflow']])}<p class="data-source">Last known snapshot. Connection errors may make these records stale.</p>`)}
function content(){if(view==='finance'&&me.role==='owner')return companyFinances();if(view==='neworganisation')return newOrganisationForm();if(view==='activity')return runtimeActivity();if(me.role==='owner'&&view==='dashboard')return stat([['Organisations',platform.organisations.length,'Current organisation workspaces'],['Active',platform.organisations.filter(w=>w.active).length,'Active organisation configurations']])+founderFinanceOverview()+organisationTable();if(view==='organisations')return organisationTable();if(view==='catalogue')return card('Available module catalogue',platform.catalogue.map(m=>`<p>${esc(moduleNames[m.id]||m.id)} · ${m.enabled?'Available':'Unavailable'} ${button(m.enabled?'Disable':'Enable','catalogue',`data-id="${m.id}" data-enabled="${m.enabled?'false':'true'}"`)}</p>`).join(''));
if(view==='platformsettings')return card('Platform plans and settings',`<p>Plan labels are configurable. Billing and payment processing are unavailable.</p><form data-form="platformsettings" class="form">${field('Owner display name','ownerName',me.name)}${field('Plans (comma separated)','plans',platform.settings.plans.join(', '))}<label><input name="registrationEnabled" type="checkbox" ${platform.settings.registrationEnabled?'checked':''}>Allow organisation registration</label><button>Save platform settings</button></form>`);let w=data.workspace,rows=data.records;if(view==='expenses')return expensePage();if(['tasks','documents','automations','integration'].includes(view))return expansionContent(w);
if(view==='dashboard')return expenseSummary()+importedDashboard(w)+liveSheetCards()+connectionCard()+card('Shared module workload',workloadChart()+stat([['Open tasks',(extended.entities||[]).filter(r=>r.type==='task'&&r.status==='open').length,'Actual scoped tasks'],['Document records',(extended.entities||[]).filter(r=>r.type==='document').length,'Actual scoped documents'],['Generated reports',(extended.entities||[]).filter(r=>r.type==='report').length,'Scheduled/local reports']]))+stat([['Saved records',rows.length,'Records available to your account'],['Working hours',rows.filter(r=>r.type==='attendance').reduce((n,r)=>n+r.hours,0).toFixed(4),'Calculated from completed shifts'],['Pending requests',rows.filter(r=>r.status==='pending').length,'Assigned/scoped requests'],['Imported rows',w.historical.length,'Labelled historical data']])+card('Enabled modules',Object.entries(w.modules).filter(([,enabled])=>enabled).map(([m])=>`<span class="chip">${esc(m)}</span>`).join(' '))+card('Recent activity',recordsTable(rows.slice(-8)));
if(view==='onboarding')return onboarding(w);
if(view==='settings')return rulesForm(w);
if(view==='people')return card('Individual accounts',table(['Name','Email','Role','Campus','Status','Action'],data.users.map(u=>[esc(u.name),esc(u.email),esc(u.kind),esc(u.location),u.active?'Active':'Inactive',u.id===me.id?'Your account':button(u.active?'Deactivate':'Activate','user',`data-id="${u.id}" data-active="${!u.active}"`)]))) +card('Edit account permissions',`<form data-form="permission" class="form">${select('Account','id',data.users.filter(u=>u.id!==me.id).map(u=>[u.id,u.name]))}${select('Permission','kind',['employee','manager','student','approver','admin'])}${select('Assigned location','location',w.locations)}<button>Save account permissions</button></form>`)+inviteForm(w);
if(view==='connections')return connectionForm(w);

if(view==='notifications')return card('Scoped notification log',data.notifications.map(n=>`<div class="activity"><b>${esc(n.text)}</b><p>${esc(n.mode)} · ${esc(n.date)}</p></div>`).join('')||'<p>No notifications.</p>');
if(view==='attendance')return (me.kind==='employee'?card('Check in / out',`<form data-form="clock" class="form">${field('Event time (local; blank uses now)','time','','datetime-local')}<label>Photo (PNG/JPEG/WebP)<input type="file" name="photo" accept="image/png,image/jpeg,image/webp" capture="user"></label>${select('Action','action',[['in','Check in'],['out','Check out']])}<button class="primary">Save attendance</button></form><p>Break deduction ${esc(w.rules.breakMinutes)} minutes; daily hours ${esc(w.rules.dailyHours)}. Photos ${w.rules.photoRequired?'required':'optional'}.</p>`):'')+card('Attendance history',recordsTable(rows.filter(r=>r.type==='attendance')))+(me.role==='admin'?card('Correct missing check-out',`<form data-form="resolve" class="form">${select('Open shift','id',rows.filter(r=>r.type==='attendance'&&!r.out).map(r=>[r.id,r.user+' · '+r.in]))}${field('Recorded check-out (local)','out','','datetime-local','required')}<button>Complete missing checkout</button></form><p>Missing end photo remains explicitly missing.</p>`):'');
if(view==='requests')return (me.kind==='student'?card('New equipment request',`<form data-form="request" class="form">${select('Campus','location',w.locations)}${select('Equipment','equipment',w.equipment.map(e=>[e.id,e.name+' · '+e.location+' · '+e.available+' available']))}${field('Quantity','qty',1,'number','min="1" required')}${field('Return due','due','','date')}<button class="primary">Submit request</button></form>`):'')+card('Requests & approvals',recordsTable(rows.filter(r=>r.type==='request')))+(me.role==='admin'?button('Run due return reminders','followups'):'');
if(view==='inventory')return card('Inventory by campus',table(['Equipment','Campus','Total','Available','Adjust'],w.equipment.map(e=>[esc(e.name),esc(e.location),e.total,e.available,`<form data-form="stock"><input name="id" type="hidden" value="${e.id}"><input name="total" type="number" value="${e.total}" min="${e.total-e.available}"><button>Adjust stock</button></form>`])))+card('Add inventory',`<form data-form="inventory" class="form">${field('Name','name','','text','required')}${select('Campus','location',w.locations)}${field('Total','total',1,'number','min="0" required')}<button>Add inventory</button></form>`);
if(view==='reports')return importedDashboard(w,true)+stat([['Visible shifts',rows.filter(r=>r.type==='attendance'&&r.out).length,'Scoped to your permission'],['Calculated hours',rows.filter(r=>r.type==='attendance').reduce((n,r)=>n+r.hours,0).toFixed(4),'Saved shift rules'],['Requests',rows.filter(r=>r.type==='request').length,'Scoped records']])+card('Records',recordsTable(rows))+card('Imported historical data',`<p>${w.historical.length} imported rows, excluded from connected totals.</p>`)+(me.role==='admin'?button('Export records CSV','export'):'');
if(view==='csv')return card('Spreadsheet-compatible CSV',`<p>Export operational records or import inventory CSV. No live Excel/Google Sheets claim is implied. Staff accounts are created through invitations.</p>${button('Export records CSV','export')}<form data-form="import" class="form"><label>Inventory CSV<input type="file" name="file" accept=".csv" required></label><p>Headers: name,location,total,available</p><button>Import inventory</button></form><form data-form="historical" class="form"><label>Historical JSON rows<input type="file" name="file" accept=".json" required></label><p>JSON array only; labelled imported history.</p><button>Import labelled history</button></form>`);
if(view==='connected')return connectedForm(w);
return ''}
function organisationTable(){let organisations=platform.organisations;return reusedModulesPanel()+`<section class="workspace-section"><div class="workspace-heading"><div><span class="eyebrow">Workspace directory</span><h2>Your organisations</h2><p>Manage access, modules and connected services in one place.</p></div><span class="directory-count">${organisations.length} workspaces</span></div><div class="workspace-grid">${organisations.map(w=>{let modules=Object.entries(w.modules).filter(([,enabled])=>enabled).map(([m])=>moduleNames[m]||m),initials=w.name.split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase(),connections=[['Data connection',w.connection?.status||'Not connected'],...(w.modules.expenses?[['Expense Excel',w.expenseConnection?.excel?.status||'Not connected'],['Teams',w.expenseConnection?.teams?.status||'Not connected']]:[])];return `<article class="workspace-tile"><div class="workspace-tile-heading"><span class="workspace-avatar">${esc(initials)}</span><div><h3>${esc(w.name)}</h3><span class="workspace-status ${w.active?'is-active':'is-paused'}">${w.active?'Active':'Inactive'}</span></div></div>${workspaceRecordMetrics(w)}<div class="workspace-modules"><span class="section-label">Enabled modules</span><div>${modules.map(m=>'<span class="module-tag">'+esc(m)+'</span>').join('')||'<span class="muted">No modules selected</span>'}</div></div><div class="workspace-connections">${connections.map(([label,status])=>'<div><span>'+esc(label)+'</span><strong class="connection-state">'+esc(status)+'</strong></div>').join('')}</div><div class="workspace-recent"><span class="section-label">Latest activity</span><p>${esc(w.activity[0]?.action?.replace(/-/g,' ')||'No activity recorded')}</p></div><div class="workspace-shortcuts">${button('Modules','workspace-step',`data-id="${w.id}" data-stage="2"`)}${button('Rules','workspace-step',`data-id="${w.id}" data-stage="5"`)}${button('Setup tests','workspace-step',`data-id="${w.id}" data-stage="7"`)}</div><div class="workspace-actions">${button('Manage workspace','selectorg',`data-id="${w.id}" class="primary"`)}${button(w.active?'Pause':'Enable','orgtoggle',`data-id="${w.id}" data-active="${!w.active}"`)}</div></article>`}).join('')}</div></section>`+organisations.map(w=>importedDashboard(w)).join('')}

function rulesForm(w){return card('Operational rules',`<form data-form="rules" class="form">${field('Plan label','plan',w.plan||'Starter')}${field('Daily regular hours','dailyHours',w.rules.dailyHours,'number','step="0.5" min="0.5" max="24" required')}${field('Break minutes','breakMinutes',w.rules.breakMinutes,'number','min="0" max="480" required')}${field('Default return days','returnDays',w.rules.returnDays,'number','min="1" max="365" required')}<label><input type="checkbox" name="photoRequired" ${w.rules.photoRequired?'checked':''}>Require attendance photos</label>${field('Collection instructions','collection',w.rules.collection)}${field('Return instructions','returns',w.rules.returns)}${me.role==='admin'?'<label><input name="ownerRecordAccess" type="checkbox" '+(w.ownerRecordAccess?'checked':'')+'>Grant and log platform owner access to organisation records</label>':''}<button>Save rules</button></form>`)}
function inviteForm(w){return card('Invite an individual user',`<form data-form="invite" class="form">${field('Email','email','','email','required')}${select('Permission','kind',['employee','manager','student','approver','admin'])}${select('Location / campus','location',w.locations)}<button>Create invitation</button></form><p>One-use invitation expires in 24 hours. Share this secure link directly with the intended recipient.</p><p id="invite-url"></p>`)}
function onboarding(w){let steps=[['Create',1],['Modules',2],['Configure',5],['Records',3],['Invite',6],['Test & activate',7]],index=w.stage===4?3:w.stage===8?5:Math.max(0,steps.findIndex(([,stage])=>stage===w.stage)),body=`<div class="setup-intro"><span class="eyebrow">Organisation setup</span><h2>${esc(w.name)}</h2><p>${esc(me.name)} · ${me.role==='owner'?'Platform owner':'Organisation administrator'} · Step ${index+1} of 6</p></div><div class="setup-progress">${steps.map(([label,stage],i)=>button(`${i+1}. ${label}`,'stage',`data-stage="${stage}" class="${i===index?'current':''}" aria-current="${i===index?'step':'false'}"`)).join('')}</div>`;
if(index===0)body+=card('Organisation details',`<form data-form="details" class="form">${field('Organisation name','name',w.name,'text','required')}${field('Locations / campuses (comma separated)','locations',w.locations.join(', '),'text','required')}<button>Save organisation</button></form><p>Next, select the shared modules your organisation needs.</p>`);
if(index===1)body+=card('Choose modules',`<p>Modules use shared OperaOS code. Saved settings determine what this organisation can access.</p><form data-form="modules" class="form setup-module-grid">${data.catalogue.map(m=>`<label><input name="${m.id}" type="checkbox" ${w.modules[m.id]?'checked':''} ${!m.enabled?'disabled':''}>${esc(moduleNames[m.id]||m.id)} ${!m.enabled?'(unavailable)':''}</label>`).join('')}<button>Save module selection</button></form>`);
if(index===2){body+=card('Locations, roles & operational rules',`<form data-form="setup-config" class="form setup-config-form">${field('Organisation name','name',w.name,'text','required')}${field('Locations / campuses (comma separated)','locations',w.locations.join(', '),'text','required')}${w.modules.attendance?field('Regular daily hours','dailyHours',w.rules.dailyHours,'number','min="0.5" max="24" step="0.5" required')+field('Break deduction (minutes)','breakMinutes',w.rules.breakMinutes,'number','min="0" max="480" required')+'<label><input name="photoRequired" type="checkbox" '+(w.rules.photoRequired?'checked':'')+'>Require check-in / out photos</label>':''}${w.modules.equipment?field('Default return period (days)','returnDays',w.rules.returnDays,'number','min="1" max="365"'):''}<button>Save configuration</button></form><p class="data-source">Rules are saved for this organisation. Attendance rules are captured at check-in, so changes do not rewrite earlier hours.</p>`);body+=card('Organisation administrators',table(['Name','Email','Status'],data.users.filter(u=>u.role==='admin').map(u=>[esc(u.name),esc(u.email),u.active?'Active':'Inactive']))+'<p>Use Invite to add an administrator with their own account.</p>');body+=card('Users and assigned approvers',table(['Name','Role','Location','Status'],data.users.filter(u=>u.role!=='admin').map(u=>[esc(u.name),esc(u.kind),esc(u.location||'—'),u.active?'Active':'Inactive']))+'<p>Users receive individual accounts through one-use invitations. Approvers must be assigned to the correct location.</p>');if(w.modules.expenses)body+=expensePage(true)}
if(index===3){if(w.modules.equipment)body+=requestSummaryForm(w);body+=card('Organisation records',stat([['Historical imports',w.historical.length,'Saved source records'],['Local operations',data.records.length,'Permitted operational records'],['Connection status',connection?.connection?.status||'Not connected','Actual adapter status']])+'<p>Select a source, map its columns and test the connection. Uploaded files and connected records remain separate.</p>');body+=integrationCentre(w);if(['attendance','equipment'].includes(w.type))body+=connectionForm(w)}
if(index===4)body+=inviteForm(w)+card('Registered organisation accounts',table(['Name','Email','Role','Location'],data.users.map(u=>[esc(u.name),esc(u.email),esc(u.kind),esc(u.location||'—')])));
if(index===5)body+=card('Test & activate',`<p>Run the configuration test to check saved settings and required approvers. External connections are verified separately.</p><div class="toolbar">${button('Run configuration test','testorg')}${button('Activate organisation','activate')}</div>${table(['Test time','Result','Details'],w.tests.map(t=>[esc(activityTime(t.date)),t.passed?'<span class="reuse-state enabled">Passed</span>':'<span class="reuse-state">Needs attention</span>',esc(t.errors.join(' ')||'Configuration checks passed')]))}<p>Workspace status: <strong>${w.active?'Active':'Not active'}</strong></p>`);
return body+`<div class="setup-footer">${index>0?button('← Previous step','stage',`data-stage="${steps[index-1][1]}"`):''}${button('Return to overview','view','data-view="'+(me.role==='owner'?'organisations':'dashboard')+'"')}${index<5?button('Continue →','stage',`data-stage="${steps[index+1][1]}" class="primary"`):''}</div>`}

function connectionForm(w){let c=connection?.connection||{};return connectionCard()+card('Per-organisation connection',`<p>Endpoint credentials come only from backend environment variables. Mapping and configuration are saved per workspace.</p><form data-form="connection" class="form">${field('Connection label','label',c.label||'Dedicated test resource')}${w.type==='attendance'?field('Test Google spreadsheet URL','sheetURL',c.sheetId?'https://docs.google.com/spreadsheets/d/'+c.sheetId+'/edit':'','url','required')+['id','organisation','employeeId','employeeName','checkIn','checkOut','hours','demo','breakMinutes','dailyHours','status'].map(k=>field('Column: '+k,k,c.mapping?.[k]||k)).join(''):''}<label><input name="testResource" type="checkbox" required>Separate test resource confirmed</label><button>Save connection mapping</button></form>${button('Test real connection','testconnection')} ${button('Sync endpoint records','sync')}<p>New workspace endpoints are supplied by an administrator in the backend environment; credentials are never editable by employees.</p>`)}
function connectedForm(w){return connectionCard()+card('Connected demonstration transaction',w.type==='attendance'?`<form data-form="connected-attendance" class="form">${me.role==='admin'?field('Demo employee ID','employeeId','DEMO-TEST')+field('Demo employee name','employeeName','Fictional employee'):''}${field('Event time (local; blank uses now)','time','','datetime-local')}${select('Action','action',[['in','Check in'],['out','Check out']])}<button>Write and read back from test sheet</button></form>`:`<form data-form="connected-request" class="form">${select('Campus','campus',w.locations)}${field('Equipment','equipment','Demonstration laptop')}${field('Quantity','quantity',1,'number','min="1" max="100"')}<button>Send to test workflow</button></form>`)+card('Endpoint records',table(['Record ID','Account / campus','Status','Hours','Action'],(connection.records||[]).map(r=>[esc(r.id),esc(r.employeeId||r.campus),esc(r.status||'saved'),esc(r.hours??'—'),w.type==='equipment'&&me.role==='admin'?button('Fetch approval status','remoteapproval',`data-id="${r.id}"`):'—'])))}
function recordsTable(rows){return table(['Record ID / source','Account','Record','Result','Action'],rows.map(r=>{let actions='';if(r.type==='request'){if(me.kind==='approver'&&r.status==='pending')actions=button('Approve','requestaction',`data-id="${r.id}" data-op="approve"`)+button('Reject','requestaction',`data-id="${r.id}" data-op="reject"`);if(me.role==='admin'&&r.status==='approved')actions=button('Issue','requestaction',`data-id="${r.id}" data-op="issue"`);if(me.role==='admin'&&r.status==='issued')actions=button('Confirm return','requestaction',`data-id="${r.id}" data-op="return"`)}return [esc(r.id)+`<br><small>${esc(r.source)}</small>`,esc(data.users.find(u=>u.id===r.user)?.name||r.user),r.type==='attendance'?esc(r.in)+' → '+esc(r.out||'Open'):esc(r.location)+' · '+esc(data.workspace.equipment.find(e=>e.id===r.equipment)?.name||r.equipment),r.type==='attendance'?Number(r.hours).toFixed(4)+' hours'+`<details><summary>Photo evidence</summary>${r.inPhoto?'<img width="130" src="'+esc(r.inPhoto)+'" alt="Check-in photo">':'Check-in photo missing'} ${r.outPhoto?'<img width="130" src="'+esc(r.outPhoto)+'" alt="Check-out photo">':'Check-out photo missing'}${r.correction?'<p>'+esc(r.correction)+'</p>':''}</details>`:esc(r.status)+(r.status==='issued'&&r.due<new Date().toISOString().slice(0,10)?' · overdue':''),actions||'—']}))}
function csvRows(text){let rows=[],row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){let c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++}else quoted=!quoted}else if(c===','&&!quoted){row.push(cell);cell=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(Boolean))rows.push(row);row=[];cell=''}else cell+=c}if(quoted)throw Error('Unclosed CSV quote');row.push(cell);if(row.some(Boolean))rows.push(row);let headers=rows.shift();return rows.map(r=>Object.fromEntries(headers.map((h,i)=>[h.trim(),r[i]?.trim()]))) }
function photo(file){return new Promise((resolve,reject)=>{if(!file||!file.size)return resolve('');if(file.size>550000)return reject(Error('Choose a photo under 550 KB.'));let r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)})}
